/**
 * RECYCLING 05 | Aluminum Renewal Can to Can
 * Pure JavaScript Canvas 2D. No assets, imports, DOM, or external dependencies.
 * Interface: draw(ctx, time, width, height). Time is already in SECONDS.
 * 25 seconds | 3 scenes | seamless loop | 16:9 | 3840 x 2160 preferred.
 * Scales uniformly to FHD, QHD and UHD. No glow, blur, or moving background.
 *
 * REQUESTED VIDEO ENCODING: 100,000,000 bits/second (100 Mbps), 60 fps.
 * Revision: synchronized machine phases, rigid transport, clean material paths.
 * Set the renderer's video bitrate to 100 Mbps or higher. Canvas draws pixels;
 * the encoding settings below are metadata, not a video encoder.
 */
const Recycling05 = (() => {
/* This core is embedded in each delivered JavaScript file; no dependencies. */
const TAU = Math.PI * 2;
const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const fract = v => v - Math.floor(v);
const mix = (a, b, p) => a + (b - a) * p;
const ease = v => { const p = clamp(v); return p*p*p*(p*(p*6-15)+10); };
const edge = (p, w = 0.09) => ease(p / w) * ease((1-p) / w);
// Shared normalized phases keep every attached part on the same motion curve.
const progress = (u, start, end) => ease((u-start)/(end-start));
const transport = (time, period, offset = 0) => fract(time/period+offset);
const FORM_PERIOD = 5;
const FORM_RADIUS = 95;
const FORM_ADVANCE = TAU*FORM_RADIUS/5;
const OUTPUT_PITCH = 601/3;

function formingCycle(time) {
  const cycles=time/FORM_PERIOD, u=fract(cycles);
  const feed=progress(u,.02,.25);
  const approach=progress(u,.30,.40);
  const press=progress(u,.40,.62);
  const retract=progress(u,.68,.98);
  return {
    // Five identical advances make one coil turn in the complete 25 s loop.
    distance: FORM_ADVANCE*(Math.floor(cycles)+feed),
    bottom: mix(345,371,approach)+50*press-76*retract,
    output: transport(time,FORM_PERIOD,-.985)
  };
}

function rr(ctx, x, y, w, h, r = 12, fill, stroke, lw = 2) {
  r = Math.min(r, w/2, h/2);
  ctx.beginPath();
  ctx.moveTo(x+r, y); ctx.lineTo(x+w-r, y);
  ctx.quadraticCurveTo(x+w, y, x+w, y+r);
  ctx.lineTo(x+w, y+h-r); ctx.quadraticCurveTo(x+w, y+h, x+w-r, y+h);
  ctx.lineTo(x+r, y+h); ctx.quadraticCurveTo(x, y+h, x, y+h-r);
  ctx.lineTo(x, y+r); ctx.quadraticCurveTo(x, y, x+r, y);
  ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

function line(ctx, x1, y1, x2, y2, color, lw = 2) {
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2);
  ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
}

function circle(ctx, x, y, r, fill, stroke, lw = 2) {
  ctx.beginPath(); ctx.arc(x,y,r,0,TAU);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

function path(ctx, points, color, lw = 2, fill = null, close = false) {
  ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
  for (let i=1; i<points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  if (close) ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (color) { ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke(); }
}

function label(ctx, value, x, y, size, color, weight = 500, maxWidth = Infinity, align = 'left') {
  ctx.save();
  ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
  ctx.font = `${weight} ${size}px Arial, Helvetica, sans-serif`;
  const measured = ctx.measureText(value).width;
  if (measured > maxWidth) {
    size *= maxWidth / measured;
    ctx.font = `${weight} ${size}px Arial, Helvetica, sans-serif`;
  }
  ctx.fillStyle = color; ctx.fillText(value,x,y); ctx.restore();
}

function arrow(ctx, x, y, size, color, angle = 0, lw = 2.5) {
  ctx.save(); ctx.translate(x,y); ctx.rotate(angle);
  path(ctx,[[-size*0.46,-size*0.38],[0,0],[-size*0.46,size*0.38]],color,lw);
  ctx.restore();
}

function roller(ctx, x, y, r, a, fill, stroke, accent) {
  circle(ctx,x,y,r,fill,stroke,2.4);
  ctx.save(); ctx.translate(x,y); ctx.rotate(a);
  for (let i=0;i<4;i++) {
    const b=i*TAU/4;
    line(ctx,Math.cos(b)*r*.35,Math.sin(b)*r*.35,
      Math.cos(b)*r*.73,Math.sin(b)*r*.73,accent,2.4);
  }
  ctx.restore(); circle(ctx,x,y,r*.18,fill,stroke,2);
}

function belt(ctx, x, y, w, h, phase, palette, count = 10) {
  rr(ctx,x,y,w,h,h/2,palette.belt,palette.border,2.2);
  // Fixed-pitch treads wrap only in the covered end rollers.
  const pitch=(w-h)/count;
  ctx.save();
  rr(ctx,x+h*.5,y+3,w-h,h-6,2); ctx.clip();
  for(let i=-1;i<=count+1;i++) {
    const px=x+h*.5+(i+fract(phase))*pitch;
    line(ctx,px,y+9,px,y+h-9,palette.beltMark,2);
  }
  ctx.restore();
  // Roller tangential speed equals tread travel: r = pitch / PI, angle = phase * PI.
  const radius=Math.min(h*.46,pitch/Math.PI);
  roller(ctx,x+h/2,y+h/2,radius,phase*Math.PI,palette.machine,palette.border,palette.muted);
  roller(ctx,x+w-h/2,y+h/2,radius,phase*Math.PI,palette.machine,palette.border,palette.muted);
  line(ctx,x+h*.7,y+h+4,x+h*.7,y+h+25,palette.border,3);
  line(ctx,x+w-h*.7,y+h+4,x+w-h*.7,y+h+25,palette.border,3);
}

function recycle(ctx, x, y, r, a, color, lw = 2.5) {
  ctx.save(); ctx.translate(x,y); ctx.rotate(a);
  for(let i=0;i<3;i++) {
    const q=-Math.PI/2+i*TAU/3;
    const end=q+TAU/3-.36;
    ctx.beginPath(); ctx.arc(0,0,r,q,end);
    ctx.strokeStyle=color; ctx.lineWidth=lw; ctx.stroke();
    arrow(ctx,Math.cos(end)*r,Math.sin(end)*r,9,color,end+Math.PI/2,lw);
  }
  ctx.restore();
}

function paper(ctx, x, bottom, scale, palette, clean = false) {
  ctx.save(); ctx.translate(x,bottom); ctx.scale(scale,scale);
  // One continuous folded-page silhouette; no diagonal through the page body.
  const body=clean?palette.paperClean:palette.paper;
  ctx.beginPath(); ctx.moveTo(-35,-94); ctx.lineTo(17,-94);
  ctx.lineTo(35,-76); ctx.lineTo(35,-4);
  ctx.quadraticCurveTo(35,0,31,0); ctx.lineTo(-31,0);
  ctx.quadraticCurveTo(-35,0,-35,-4); ctx.closePath();
  ctx.fillStyle=body; ctx.fill(); ctx.strokeStyle=palette.paperInk; ctx.lineWidth=3; ctx.stroke();
  path(ctx,[[17,-93],[17,-76],[34,-76]],palette.paperInk,2.5);
  if(!clean) {
    for(let i=0;i<4;i++) line(ctx,-20,-62+i*12,i===3?4:19,-62+i*12,palette.paperInk,2.3);
  } else {
    line(ctx,-20,-62,8,-62,palette.paperDetail,2.3);
    line(ctx,-20,-50,20,-50,palette.paperDetail,2.3);
  }
  ctx.restore();
}

function phaseTitle(ctx, n, title, description, palette) {
  rr(ctx,52,35,42,34,10,palette.tag,palette.border,1.8);
  label(ctx,`0${n}`,73,58,15,palette.accent,700,28,'center');
  label(ctx,title,110,59,21,palette.text,700,1450);
  label(ctx,description,52,94,16,palette.muted,400,1550);
}

function pipe(ctx,x1,x2,y,phase,palette,width=22) {
  line(ctx,x1,y,x2,y,palette.border,width+4);
  line(ctx,x1,y,x2,y,palette.pipe,width);
  const count=Math.max(2,Math.floor((x2-x1)/48));
  for(let i=0;i<count;i++) {
    const u=fract(i/count+phase);
    ctx.save(); ctx.globalAlpha*=edge(u,.14);
    line(ctx,mix(x1+12,x2-20,u),y,mix(x1+12,x2-20,u)+9,y,palette.accent,3);
    ctx.restore();
  }
}

function footer(ctx, timeline, palette, names) {
  const transition=timeline.transition;
  const weights=[0,0,0];
  weights[timeline.currentScene]=1-transition;
  weights[(timeline.currentScene+1)%3]+=transition;
  const positions=[112,700,1288];
  line(ctx,112,934,1808,934,palette.rule,1.4);
  names.forEach((name,i)=>{
    const x=positions[i];
    rr(ctx,x,958,34,34,10,palette.tag,palette.border,1.8);
    label(ctx,`0${i+1}`,x+17,981,13,palette.muted,700,25,'center');
    label(ctx,name,x+50,980,17,palette.muted,600,390);
    ctx.save(); ctx.globalAlpha*=weights[i];
    rr(ctx,x,958,34,34,10,palette.accent);
    label(ctx,`0${i+1}`,x+17,981,13,palette.accentInk,700,25,'center');
    label(ctx,name,x+50,980,17,palette.text,700,390);
    line(ctx,x+50,996,x+430,996,palette.accent,2.4);
    ctx.restore();
  });
}

function sceneWindow(ctx,timeline,palette,scenes) {
  const X=96,Y=230,W=1728,H=670;
  const surface=ctx.createLinearGradient(X,Y,X+W,Y+H);
  surface.addColorStop(0,palette.panelA); surface.addColorStop(1,palette.panelB);
  rr(ctx,X,Y,W,H,28,surface,palette.border,2);
  // The drawing surface and its stationary reference marks never move.
  for(let i=0;i<9;i++) circle(ctx,X+44+i*205,Y+H-27,1.4,palette.rule);
  ctx.save(); rr(ctx,X+2,Y+2,W-4,H-4,26); ctx.clip(); ctx.translate(X,Y);
  const s=timeline.transition;
  const indices=s>0?[timeline.currentScene,(timeline.currentScene+1)%3]:[timeline.currentScene];
  indices.forEach((index,j)=>{
    const offset=j===0?-s*W:(1-s)*W;
    ctx.save(); ctx.translate(offset,0);
    // Independent windows guarantee that moving scenes cannot overlap.
    ctx.beginPath(); ctx.rect(0,0,W,H); ctx.clip();
    scenes[index](ctx,timeline,palette);
    ctx.restore();
  });
  ctx.restore();
}

const P = {
  text:'#294F62', muted:'#65808D', border:'#91ADB7', rule:'#C8D9DC',
  accent:'#427E73', accentInk:'#F2F8F4', tag:'#DEEBE8',
  panelA:'#F1F6F5', panelB:'#E5EEF1', machine:'#D2E1E5', inset:'#F0F6F6',
  belt:'#BCD2DA', beltMark:'#86A4B2', pipe:'#DFECEC',
  metal:'#C0D4DD', metalInk:'#4B7182', mint:'#8BB8A6', silver:'#DFE9EA',
  melt:'#ADCBCB', warm:'#B6AB8B'
};

function background(ctx,width,height) {
  const g=ctx.createLinearGradient(0,0,width,height);
  g.addColorStop(0,'#E7EEF2'); g.addColorStop(.53,'#D9E5E9'); g.addColorStop(1,'#C9DDD8');
  ctx.fillStyle=g; ctx.fillRect(0,0,width,height);
  ctx.save(); ctx.strokeStyle='rgba(64,106,117,0.065)';
  ctx.lineWidth=Math.min(width,height)*.0011;
  for(let i=0;i<4;i++) {
    const x=width*(.74+i*.055);
    ctx.beginPath(); ctx.moveTo(x,-height*.02); ctx.lineTo(x,height*.09);
    ctx.quadraticCurveTo(x,height*.19,x+height*.1,height*.19);
    ctx.lineTo(width*1.03,height*(.19+i*.045)); ctx.stroke();
  }
  for(let i=0;i<3;i++) {
    ctx.beginPath(); ctx.arc(width*.025,height*1.03,height*(.14+i*.05),Math.PI,TAU); ctx.stroke();
  }
  ctx.restore();
}

function can(ctx,x,bottom,s=1,compression=0) {
  ctx.save(); ctx.translate(x,bottom); ctx.scale(s,s);
  const k=clamp(compression), h=94-58*k, half=28;
  // Only the intentional press operation changes the silhouette. Its folded
  // sides are mirrored; transported cans always use the exact rigid profile.
  const inset=4*k, ridge=2*k;
  ctx.beginPath(); ctx.moveTo(-half+8,-h); ctx.lineTo(half-8,-h);
  ctx.quadraticCurveTo(half,-h,half,-h+8);
  ctx.lineTo(half,-h*.74);
  ctx.lineTo(half-inset,-h*.61);
  ctx.lineTo(half+ridge,-h*.48);
  ctx.lineTo(half-inset,-h*.35);
  ctx.lineTo(half,-8);
  ctx.quadraticCurveTo(half,0,half-8,0);
  ctx.lineTo(-half+8,0);
  ctx.quadraticCurveTo(-half,0,-half,-8);
  ctx.lineTo(-half+inset,-h*.35);
  ctx.lineTo(-half-ridge,-h*.48);
  ctx.lineTo(-half+inset,-h*.61);
  ctx.lineTo(-half,-h*.74); ctx.lineTo(-half,-h+8);
  ctx.quadraticCurveTo(-half,-h,-half+8,-h); ctx.closePath();
  ctx.fillStyle=P.metal; ctx.fill();
  ctx.strokeStyle=P.metalInk; ctx.lineWidth=2.8; ctx.stroke();
  line(ctx,-21,-h+8,21,-h+8,P.metalInk,2.1);
  rr(ctx,-7,-h+2.5,14,3.5,1.75,P.metalInk);
  line(ctx,-21,-8,21,-8,P.metalInk,2);
  ctx.save(); ctx.globalAlpha*=1-k;
  line(ctx,-16,-h+21,-16,-18,P.metalInk,1.9); ctx.restore();
  if(k>0) {
    ctx.save(); ctx.globalAlpha*=k;
    path(ctx,[[-20,-h*.58],[-10,-h*.46],[0,-h*.58],[10,-h*.46],[20,-h*.58]],P.metalInk,1.6);
    ctx.restore();
  }
  ctx.restore();
}

function bale(ctx,x,bottom,s=1) {
  ctx.save(); ctx.translate(x,bottom); ctx.scale(s,s);
  rr(ctx,-54,-46,108,46,6,P.metal,P.metalInk,2.6);
  path(ctx,[[-44,-32],[-28,-26],[-9,-33],[10,-25],[29,-31],[44,-26]],P.metalInk,1.7);
  path(ctx,[[-44,-16],[-22,-21],[-4,-14],[15,-20],[34,-13],[44,-18]],P.metalInk,1.7);
  rr(ctx,-32,-45,9,44,2,P.mint,P.metalInk,1.4);
  rr(ctx,23,-45,9,44,2,P.mint,P.metalInk,1.4);
  ctx.restore();
}

function coil(ctx,x,y,r,a) {
  circle(ctx,x,y,r,P.silver,P.metalInk,2.8);
  ctx.save(); ctx.translate(x,y); ctx.rotate(a);
  // A flat spiral cross-section. No perspective faces, speculars, or shadows.
  ctx.beginPath();
  for(let i=0;i<=180;i++) {
    const u=i/180, angle=u*TAU*3, radius=mix(r*.24,r*.92,u);
    const px=Math.cos(angle)*radius, py=Math.sin(angle)*radius;
    if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
  }
  ctx.strokeStyle=P.metalInk; ctx.lineWidth=2; ctx.stroke(); ctx.restore();
  circle(ctx,x,y,r*.18,P.machine,P.metalInk,2.1);
  circle(ctx,x,y,r*.065,P.metalInk);
}

function web(ctx,x1,x2,y,distance,r=100) {
  rr(ctx,x1,y-5,x2-x1,10,3,P.silver,P.metalInk,1.6);
  // All visible sections use one world-space pitch and material displacement.
  // Passing through a housing cannot change the registration of the strip.
  const pitch=TAU*r/6, shift=fract(distance/pitch)*pitch;
  const first=Math.floor((x1-shift)/pitch)-1;
  const last=Math.ceil((x2-shift)/pitch)+1;
  ctx.save(); ctx.beginPath(); ctx.rect(x1+1,y-3,x2-x1-2,6); ctx.clip();
  for(let i=first;i<=last;i++) {
    const x=i*pitch+shift;
    line(ctx,x,y,x+18,y,P.border,1.8);
  }
  ctx.restore();
}

function header(ctx) {
  label(ctx,'CIRCULAR MATERIALS / ALUMINUM RECOVERY',112,86,14,P.accent,700,1100);
  label(ctx,'ALUMINUM RENEWAL',110,143,47,P.text,700,1070);
  label(ctx,'From used cans to a fresh material cycle.',112,181,19,P.muted,400,1090);
  rr(ctx,1281,101,526,65,17,P.tag,P.border,1.7);
  can(ctx,1317,153,.37);
  label(ctx,'CANS',1343,139,12,P.text,700,100);
  line(ctx,1437,116,1437,151,P.border,1.3);
  circle(ctx,1466,134,13,P.silver,P.metalInk,1.5);
  circle(ctx,1466,134,6,null,P.metalInk,1.3);
  label(ctx,'SHEET',1490,139,12,P.text,700,100);
  line(ctx,1590,116,1590,151,P.border,1.3);
  recycle(ctx,1621,134,13,0,P.accent,1.8);
  label(ctx,'REMAKE',1646,139,12,P.text,700,140);
}

function compact(ctx,q,p) {
  const c=q.loopT/q.duration, u=transport(q.loopT,5);
  phaseTitle(ctx,1,'COLLECT & COMPACT','A steady can stream enters an enclosed, controlled compaction chamber.',p);

  // Exactly three inlet cans and one outlet bale per five-second batch.
  // Conveyor travel and object travel are derived from the same distances.
  belt(ctx,125,450,650,44,c*65,p,12);
  belt(ctx,1030,450,600,44,c*60,p,12);
  for(let i=0;i<3;i++) can(ctx,mix(152,808.5,fract(q.loopT/5+i/3)),447.72,.84);
  bale(ctx,mix(1000,1556,transport(q.loopT,5,.22)),447.6,1);

  rr(ctx,648,180,410,365,23,p.machine,p.border,2.6);
  label(ctx,'CONTROLLED COMPACTION',853,219,16,p.text,700,355,'center');
  rr(ctx,674,255,358,218,13,p.inset,p.border,1.9);
  const compression=progress(u,.28,.58);
  const canBottom=447.1, contact=canBottom-94;
  const platenBottom=mix(333,contact,progress(u,.14,.28))+
    58*compression-(contact+58-333)*progress(u,.66,.84);

  ctx.save(); rr(ctx,675,256,356,216,12); ctx.clip();
  line(ctx,699,274,699,453,p.border,3.4);
  line(ctx,1007,274,1007,453,p.border,3.4);
  [760,853,946].forEach(x=>can(ctx,x,canBottom,1,compression));
  rr(ctx,835,248,36,platenBottom-266,5,p.metal,p.metalInk,1.9);
  rr(ctx,709,platenBottom-18,288,18,5,p.mint,p.metalInk,2.1);
  line(ctx,692,450,1014,450,p.metalInk,3);

  // Two rigid leaves translate into side pockets. The hidden batch resets
  // only after the doors have fully closed; no can or tool pose pops in view.
  const covered=1-progress(u,.02,.14)+progress(u,.84,.96);
  const travel=178*(1-covered);
  [675-travel,853+travel].forEach(x=>{
    rr(ctx,x,256,178,216,0,'#CBDDE1',p.border,1.6);
    line(ctx,x+16,279,x+16,449,p.border,1.7);
    line(ctx,x+162,279,x+162,449,p.border,1.7);
  });
  ctx.restore();
  rr(ctx,674,255,358,218,13,null,p.border,1.9);
  label(ctx,'ENCLOSED PRESS CYCLE',853,512,12,p.muted,600,350,'center');

  rr(ctx,75,317,159,136,15,p.machine,p.border,2.2);
  label(ctx,'USED CANS',154.5,346,12,p.text,700,130,'center');
  rr(ctx,92,360,125,73,8,p.inset,p.border,1.5);
  [129,180].forEach(x=>can(ctx,x,424,.54));
  rr(ctx,1494,322,163,131,15,p.machine,p.border,2.2);
  label(ctx,'COMPACTED',1575.5,348,11,p.text,700,136,'center');
  bale(ctx,1575.5,386,.68); bale(ctx,1575.5,427,.68);
  [[154.5,'RECOVERED CANS'],[853,'CONTROLLED PRESSURE'],[1575.5,'COMPACTED ALUMINUM']].forEach(([x,name])=>{
    circle(ctx,x,578,3.8,p.accent);
    label(ctx,name,x,608,12,p.muted,600,410,'center');
  });
}

function remeltAndRoll(ctx,q,p) {
  const c=q.loopT/q.duration;
  // Constant line speed drives sheet registration, both roll pairs and coil.
  const distance=c*TAU*100*5;
  phaseTitle(ctx,2,'REMELT, CAST & ROLL','Recovered aluminum becomes a continuous sheet for the next manufacturing stage.',p);

  rr(ctx,506,421,211,30,8,p.pipe,p.border,1.8);
  web(ctx,680,1515,436,distance,100);
  line(ctx,1380,548,1649,548,p.border,3);
  line(ctx,1400,548,1400,336,p.border,3);
  line(ctx,1630,548,1630,336,p.border,3);
  line(ctx,1400,336,1630,336,p.border,2.2);

  rr(ctx,78,185,450,363,22,p.machine,p.border,2.5);
  label(ctx,'REMELT',303,221,16,p.text,700,380,'center');
  for(let i=0;i<10;i++) rr(ctx,105+i*40,242,24,6,2,p.warm);
  rr(ctx,101,267,404,207,12,p.inset,p.border,1.8);
  ctx.save(); rr(ctx,103,269,400,203,10); ctx.clip();
  // Rigid bales descend from the feed openings and disappear below the bath.
  // Every reset occurs fully behind the opening or the opaque liquid layer.
  for(let i=0;i<3;i++) {
    const u=transport(q.loopT,5,i/3);
    bale(ctx,177+i*126,mix(263,441,progress(u,.10,.84)),.69);
  }
  ctx.beginPath();
  for(let i=0;i<=32;i++) {
    const x=102+i*403/32, y=389+Math.sin(TAU*(i/24-c*3))*1.4;
    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.lineTo(505,474); ctx.lineTo(102,474); ctx.closePath();
  ctx.fillStyle=p.melt; ctx.fill();
  for(let i=0;i<6;i++) {
    const u=fract(c*3+i/6), x=mix(114,478,u);
    ctx.save(); ctx.globalAlpha*=edge(u,.12);
    line(ctx,x,436,x+14,436,p.metalInk,2); ctx.restore();
  }
  ctx.restore();
  for(let i=0;i<3;i++) rr(ctx,135+i*126,266,84,13,3,p.machine,p.border,1.3);
  rr(ctx,101,267,404,207,12,null,p.border,1.8);
