    label(ctx,`0${i+1}`,x+17,981,13,palette.accentInk,700,25,'center');
    label(ctx,name,x+50,980,17,palette.text,700,390);
    line(ctx,x+50,996,x+430,996,palette.accent,2.4);
    ctx.restore();
