  for(let j=0;j<4;j++) {
    const x=width*(.75+j*.05);
    ctx.beginPath(); ctx.moveTo(x,-height*.03); ctx.lineTo(x,height*.1);
    ctx.quadraticCurveTo(x,height*.19,x+height*.09,height*.19);
