function selectorRoute(ctx,x,y1,y2,phase,k) {
  // A schematic transfer route, not a physical pipe for whole containers.
  ctx.beginPath();
  for(let i=0;i<=32;i++) {
    const u=i/32, px=x-104*ease(u), py=mix(y1,y2,u);
    if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
  }
  ctx.strokeStyle=P.border; ctx.lineWidth=2.5; ctx.stroke();
  for(let j=0;j<3;j++) {
    const u=fract(phase+j/3);
    const px=mix(x,x-104,ease(u)), py=mix(y1,y2,u);
    ctx.save(); ctx.globalAlpha*=edge(u,.16);
