  }
  ctx.lineTo(x+w,y+14); ctx.lineTo(x,y+14); ctx.closePath();
  ctx.fillStyle=P.melt[k]; ctx.fill();
  for(let i=0;i<8;i++) {
    const u=fract(c*3+i/8+phaseOffset), px=mix(x+5,x+w-25,u);
    ctx.save(); ctx.globalAlpha*=edge(u,.1)*.75;
    line(ctx,px,y+1,px+15,y+1,P.fills[k],2); ctx.restore();
