function remelt(ctx,q,p) {
  const c=q.loopT/q.duration;
  phaseTitle(ctx,2,'REMELT IN ISOLATED CHANNELS','Sorted cullet becomes molten glass while each color stream stays separate.',p);
  const rows=[260,390,520];

