    circle(ctx,96,y-31,4,p.colors[k]);
    label(ctx,p.names[k]+' CULLET',109,y-26,12,p.text,700,220);
    for(let row=0;row<2;row++) for(let j=0;j<4;j++) shard(ctx,112+j*67,y+1+row*30,k,.73,(j%2?-.15:.1));

    rr(ctx,1355,y-55,300,110,13,p.inset,p.border,2);
    label(ctx,p.names[k]+' MELT',1505,y-26,12,p.text,700,250,'center');
    rr(ctx,1374,y-9,262,43,7,p.machine,p.border,1.5);
