function moldPair(ctx,x,bottom,k,c,jar=false) {
  const bodyScale=jar?.92:.80;
  const centerOffset=(jar?53:40)+11*(.5-.5*Math.cos(TAU*(c*5+k*.13)));
  const plateWidth=24;
  const top=jar?bottom-88:bottom-111;
  const plateHeight=jar?93:116;
  line(ctx,x-centerOffset-27,top-6,x+centerOffset+27,top-6,P.border,2.3);
  line(ctx,x-centerOffset-27,bottom+9,x+centerOffset+27,bottom+9,P.border,2.3);
  [-1,1].forEach(sign=>{
    rr(ctx,x+sign*centerOffset-plateWidth/2,top,plateWidth,plateHeight,6,P.machine,P.border,1.8);
    line(ctx,x+sign*centerOffset,top+18,x+sign*centerOffset,bottom-13,P.colors[k],1.8);
  });
  // Only the plates translate. The glass silhouette keeps its exact proportions.
  glass(ctx,x,bottom,bodyScale,k,jar);
  const rimY=bottom-(jar?80:111)*bodyScale;
  rr(ctx,x-9,top-16,18,9,3,P.colors[k]);
  line(ctx,x,top-7,x,rimY-7,P.colors[k],3);
}

