function render(ctx,timeline) {
  header(ctx);
  sceneWindow(ctx,timeline,P,[separate,remelt,reform]);
  footer(ctx,timeline,P,['SEPARATE COLOR','REMELT','REFORM']);
}

  return { background, render };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0 && Number.isFinite(t) && t >= 0)) return;

  // A one-second quintic transition has zero velocity and acceleration at
  // both ends. Each scene occupies its own non-overlapping clipped window.
  const rawTransition = Math.max(0, Math.min(1, (sceneProgress - 0.88) / 0.12));
  const transition = rawTransition * rawTransition * rawTransition *
    (rawTransition * (rawTransition * 6 - 15) + 10);
  const scale = Math.min(minSide / 1080, width / 1920, height / 1080);

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.setLineDash([]);
    Recycling04.background(ctx, width, height);
    ctx.translate((width - 1920 * scale) / 2, (height - 1080 * scale) / 2);
    ctx.scale(scale, scale);
    Recycling04.render(ctx, {
      t, loopT, duration, sceneCount, sceneDuration,
      currentScene, sceneProgress, transition, minSide
    });
  } finally {
    ctx.restore();
  }
}

