/**
 * RECYCLING 02 | Paper Reborn Fiber Recovery
 * Pure JavaScript Canvas 2D. No assets, imports, DOM, or external dependencies.
 * Interface: draw(ctx, time, width, height). Time is already in SECONDS.
 * 25 seconds | 3 scenes | seamless loop | 16:9 | 3840 x 2160 preferred.
 * Scales uniformly to FHD, QHD and UHD. No glow, blur, or moving background.
 * Revised: shared material speeds, tangent-following offcuts, matched sheet
 * geometry, stable local anchors and restrained, non-overlapping scene handoffs.
 *
 * REQUESTED VIDEO ENCODING: 100,000,000 bits/second (100 Mbps), 60 fps.
 * Set the renderer's video bitrate to 100 Mbps or higher. Canvas draws pixels;
 * the encoding settings below are metadata, not a video encoder.
 */
const Recycling02 = (() => {
/* This core is embedded in each delivered JavaScript file; no dependencies. */
const TAU = Math.PI * 2;
const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const fract = v => v - Math.floor(v);
const mix = (a, b, p) => a + (b - a) * p;
const ease = v => { const p = clamp(v); return p*p*p*(p*(p*6-15)+10); };
const edge = (p, w = 0.09) => ease(p / w) * ease((1-p) / w);

function rr(ctx, x, y, w, h, r = 12, fill, stroke, lw = 2) {
  r = Math.min(r, w/2, h/2);
  ctx.beginPath();
  ctx.moveTo(x+r, y); ctx.lineTo(x+w-r, y);
  ctx.quadraticCurveTo(x+w, y, x+w, y+r);
  ctx.lineTo(x+w, y+h-r); ctx.quadraticCurveTo(x+w, y+h, x+w-r, y+h);
  ctx.lineTo(x+r, y+h); ctx.quadraticCurveTo(x, y+h, x, y+h-r);
  ctx.lineTo(x, y+r); ctx.quadraticCurveTo(x, y, x+r, y);
  ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

function line(ctx, x1, y1, x2, y2, color, lw = 2) {
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2);
  ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
}

function circle(ctx, x, y, r, fill, stroke, lw = 2) {
  ctx.beginPath(); ctx.arc(x,y,r,0,TAU);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

function path(ctx, points, color, lw = 2, fill = null, close = false) {
  ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
  for (let i=1; i<points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  if (close) ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (color) { ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke(); }
}

function label(ctx, value, x, y, size, color, weight = 500, maxWidth = Infinity, align = 'left') {
  ctx.save();
  ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
  ctx.font = `${weight} ${size}px Arial, Helvetica, sans-serif`;
  const measured = ctx.measureText(value).width;
  if (measured > maxWidth) {
    size *= maxWidth / measured;
    ctx.font = `${weight} ${size}px Arial, Helvetica, sans-serif`;
  }
  ctx.fillStyle = color; ctx.fillText(value,x,y); ctx.restore();
}

function arrow(ctx, x, y, size, color, angle = 0, lw = 2.5) {
  ctx.save(); ctx.translate(x,y); ctx.rotate(angle);
  path(ctx,[[-size*0.46,-size*0.38],[0,0],[-size*0.46,size*0.38]],color,lw);
  ctx.restore();
}

function roller(ctx, x, y, r, a, fill, stroke, accent) {
  circle(ctx,x,y,r,fill,stroke,2.4);
  ctx.save(); ctx.translate(x,y); ctx.rotate(a);
  for (let i=0;i<4;i++) {
    const b=i*TAU/4;
    line(ctx,Math.cos(b)*r*.35,Math.sin(b)*r*.35,
      Math.cos(b)*r*.73,Math.sin(b)*r*.73,accent,2.4);
  }
  ctx.restore(); circle(ctx,x,y,r*.18,fill,stroke,2);
}

function belt(ctx, x, y, w, h, phase, palette, count = 10) {
  rr(ctx,x,y,w,h,h/2,palette.belt,palette.border,2.2);
  // Fixed-pitch treads wrap only in the covered end rollers.
  const pitch=(w-h)/count;
  ctx.save();
  rr(ctx,x+h*.5,y+3,w-h,h-6,2); ctx.clip();
  for(let i=-1;i<=count+1;i++) {
    const px=x+h*.5+(i+fract(phase))*pitch;
    line(ctx,px,y+9,px,y+h-9,palette.beltMark,2);
  }
  ctx.restore();
  // Roller tangential speed equals tread travel; positive phase feeds right.
  const radius=Math.min(h*.46,pitch/Math.PI);
  roller(ctx,x+h/2,y+h/2,radius,phase*Math.PI,palette.machine,palette.border,palette.muted);
  roller(ctx,x+w-h/2,y+h/2,radius,phase*Math.PI,palette.machine,palette.border,palette.muted);
  line(ctx,x+h*.7,y+h+4,x+h*.7,y+h+25,palette.border,3);
  line(ctx,x+w-h*.7,y+h+4,x+w-h*.7,y+h+25,palette.border,3);
}

function recycle(ctx, x, y, r, a, color, lw = 2.5) {
  ctx.save(); ctx.translate(x,y); ctx.rotate(a);
  for(let i=0;i<3;i++) {
    const q=-Math.PI/2+i*TAU/3;
    const end=q+TAU/3-.36;
    ctx.beginPath(); ctx.arc(0,0,r,q,end);
    ctx.strokeStyle=color; ctx.lineWidth=lw; ctx.stroke();
    arrow(ctx,Math.cos(end)*r,Math.sin(end)*r,9,color,end+Math.PI/2,lw);
  }
  ctx.restore();
}

function paper(ctx, x, bottom, scale, palette, clean = false) {
  ctx.save(); ctx.translate(x,bottom); ctx.scale(scale,scale);
  // One continuous folded-page silhouette; no diagonal through the page body.
  const body=clean?palette.paperClean:palette.paper;
  ctx.beginPath(); ctx.moveTo(-35,-94); ctx.lineTo(17,-94);
  ctx.lineTo(35,-76); ctx.lineTo(35,-4);
  ctx.quadraticCurveTo(35,0,31,0); ctx.lineTo(-31,0);
  ctx.quadraticCurveTo(-35,0,-35,-4); ctx.closePath();
  ctx.fillStyle=body; ctx.fill(); ctx.strokeStyle=palette.paperInk; ctx.lineWidth=3; ctx.stroke();
  path(ctx,[[17,-93],[17,-76],[34,-76]],palette.paperInk,2.5);
  if(!clean) {
    for(let i=0;i<4;i++) line(ctx,-20,-62+i*12,i===3?4:19,-62+i*12,palette.paperInk,2.3);
  } else {
    line(ctx,-20,-62,8,-62,palette.paperDetail,2.3);
    line(ctx,-20,-50,20,-50,palette.paperDetail,2.3);
  }
  ctx.restore();
}

function phaseTitle(ctx, n, title, description, palette) {
  rr(ctx,52,35,42,34,10,palette.tag,palette.border,1.8);
  label(ctx,`0${n}`,73,58,15,palette.accent,700,28,'center');
  label(ctx,title,110,59,21,palette.text,700,1450);
  label(ctx,description,52,94,16,palette.muted,400,1550);
}

function pipe(ctx,x1,x2,y,phase,palette,width=22) {
  line(ctx,x1,y,x2,y,palette.border,width+4);
  line(ctx,x1,y,x2,y,palette.pipe,width);
  flowMarks(ctx,x1+17,x2-17,y,phase,palette.accent,9,3);
}

// Spatially repeated marks share one pitch and one speed across every module.
// A mark fades completely before it wraps; no particle changes scale or shape.
function flowMarks(ctx,x1,x2,y,phase,color,length=17,lw=2,curved=false,clearance=null,pitch=48) {
  const offset=fract(phase)*pitch;
  const margin=14+length*.5;
  for(let i=-1;i<=Math.ceil((x2-x1)/pitch);i++) {
    const x=x1+i*pitch+offset;
    if(x<=x1 || x>=x2) continue;
    const opacity=ease((x-x1)/margin)*ease((x2-x)/margin)*
      (clearance?clearance(x):1);
    if(opacity<=0) continue;
    ctx.save(); ctx.globalAlpha*=opacity;
    if(curved) fiberDash(ctx,x,y,length,color);
    else line(ctx,x-length*.5,y,x+length*.5,y,color,lw);
    ctx.restore();
  }
}

function footer(ctx, timeline, palette, names) {
  const transition=timeline.transition;
  const weights=[0,0,0];
  weights[timeline.currentScene]=1-transition;
  weights[(timeline.currentScene+1)%3]+=transition;
  const positions=[112,700,1288];
  line(ctx,112,934,1808,934,palette.rule,1.4);
  names.forEach((name,i)=>{
    const x=positions[i];
    rr(ctx,x,958,34,34,10,palette.tag,palette.border,1.8);
    label(ctx,`0${i+1}`,x+17,981,13,palette.muted,700,25,'center');
    label(ctx,name,x+50,980,17,palette.muted,600,390);
    ctx.save(); ctx.globalAlpha*=weights[i];
    rr(ctx,x,958,34,34,10,palette.accent);
    label(ctx,`0${i+1}`,x+17,981,13,palette.accentInk,700,25,'center');
    label(ctx,name,x+50,980,17,palette.text,700,390);
    line(ctx,x+50,996,x+430,996,palette.accent,2.4);
    ctx.restore();
  });
}

function sceneWindow(ctx,timeline,palette,scenes) {
  const X=96,Y=230,W=1728,H=670;
  const surface=ctx.createLinearGradient(X,Y,X+W,Y+H);
  surface.addColorStop(0,palette.panelA); surface.addColorStop(1,palette.panelB);
  rr(ctx,X,Y,W,H,28,surface,palette.border,2);
  // The drawing surface and its stationary reference marks never move.
  for(let i=0;i<9;i++) circle(ctx,X+44+i*205,Y+H-27,1.4,palette.rule);
  ctx.save(); rr(ctx,X+2,Y+2,W-4,H-4,26); ctx.clip(); ctx.translate(X,Y);
  const s=timeline.rawTransition;
  // Complete scenes hand off through a short, eased drift. Only one scene is
  // visible at a time, so titles, machines and particles never interpenetrate.
  const incoming=s>=.5;
  const progress=ease(incoming?(s-.5)*2:s*2);
  const opacity=incoming?progress:1-progress;
  const index=incoming?(timeline.currentScene+1)%3:timeline.currentScene;
  const offset=incoming?42*(1-progress):-42*progress;
  if(opacity>0) {
    ctx.save(); ctx.globalAlpha*=opacity; ctx.translate(offset,0);
    scenes[index](ctx,timeline,palette);
    ctx.restore();
  }
  ctx.restore();
}

const P = {
