// A single C2-continuous centerline serves the chute and every moving offcut.
// Arc-length lookup prevents a cubic curve from accelerating the material.
function chutePoint(u) {
  const v=1-u;
  const x=v*v*v*1014+3*v*v*u*1102+3*v*u*u*1198+u*u*u*1302;
  const y=v*v*v*390+3*v*v*u*390+3*v*u*u*469+u*u*u*469;
  const dx=3*v*v*(1102-1014)+6*v*u*(1198-1102)+3*u*u*(1302-1198);
  const dy=6*v*u*(469-390);
  return {x,y,angle:Math.atan2(dy,dx)};
}

const CHUTE = (()=>{
  const samples=[{u:0,d:0}], count=160;
  let last=chutePoint(0), distance=0;
  for(let i=1;i<=count;i++) {
    const u=i/count, next=chutePoint(u);
    distance+=Math.hypot(next.x-last.x,next.y-last.y);
    samples.push({u,d:distance}); last=next;
  }
  return {samples,length:distance};
})();

function chutePose(progress) {
  const distance=clamp(progress)*CHUTE.length;
  let lo=0, hi=CHUTE.samples.length-1;
  while(hi-lo>1) {
    const mid=(lo+hi)>>1;
    if(CHUTE.samples[mid].d<distance) lo=mid; else hi=mid;
  }
  const a=CHUTE.samples[lo], b=CHUTE.samples[hi];
  return chutePoint(mix(a.u,b.u,(distance-a.d)/(b.d-a.d)));
}

function chute(ctx,p) {
  ctx.save();
  ctx.beginPath(); ctx.moveTo(1014,390);
  ctx.bezierCurveTo(1102,390,1198,469,1302,469);
  ctx.strokeStyle=p.border; ctx.lineWidth=44; ctx.stroke();
  ctx.strokeStyle=p.inset; ctx.lineWidth=39; ctx.stroke();
  ctx.restore();
}

function background(ctx,width,height) {
  const g=ctx.createLinearGradient(0,0,width,height);
  g.addColorStop(0,'#F1EEE1'); g.addColorStop(.50,'#E4ECE2'); g.addColorStop(1,'#C9DFE1');
  ctx.fillStyle=g; ctx.fillRect(0,0,width,height);
  ctx.save(); ctx.strokeStyle='rgba(67,113,103,0.075)';
  ctx.lineWidth=Math.min(width,height)*.0011;
  for(let i=0;i<4;i++) {
    ctx.beginPath(); ctx.arc(width*.985,height*.04,height*(.14+i*.041),0,TAU); ctx.stroke();
  }
  for(let i=0;i<3;i++) {
    ctx.beginPath(); ctx.moveTo(-width*.02,height*(.70+i*.045));
    ctx.lineTo(width*.043,height*(.70+i*.045));
    ctx.quadraticCurveTo(width*.11,height*(.70+i*.045),width*.11,height*(.83+i*.045));
    ctx.lineTo(width*.11,height*1.03); ctx.stroke();
  }
  ctx.restore();
}

