function collect(ctx,q,p) {
  const c=q.loopT/q.duration;
  phaseTitle(ctx,1,'COLLECT & PREPARE','Recovered paper enters a steady, enclosed shredding process.',p);

  // Incoming sheets stay in separated, equal-pitch slots on the feed belt.
  const feedPhase=c*MOTION.feedCycles;
  const feedDistance=feedPhase*(MOTION.feedEnd-MOTION.feedStart);
  belt(ctx,105,439,601,46,feedDistance/MOTION.feedPitch,p,12);
  for(let i=0;i<MOTION.feedCount;i++) {
    const u=fract(feedPhase+i/MOTION.feedCount);
    paper(ctx,mix(MOTION.feedStart,MOTION.feedEnd,u),433,1,p,false);
  }
  rr(ctx,77,307,111,134,13,p.machine,p.border,2.4);
  rr(ctx,94,328,77,28,7,p.inset,p.border,1.6);
  arrow(ctx,148,342,18,p.accent);
  line(ctx,100,382,161,382,p.border,2);
  line(ctx,100,396,146,396,p.border,2);
  label(ctx,'RECOVERED PAPER',105,535,14,p.muted,600,470);
  line(ctx,105,551,586,551,p.rule,1.8);
  [0,1,2].forEach(j=>{
    rr(ctx,105+j*154,574,137,34,9,p.tag,p.border,1.3);
    label(ctx,['DOCUMENTS','PACKAGING','OFFCUTS'][j],173+j*154,596,10,p.text,600,120,'center');
  });

  // Shredding module masks the paper only after it reaches the real intake.
  chute(ctx,p);
  rr(ctx,646,218,365,317,22,p.machine,p.border,2.8);
  panelBolts(ctx,646,218,365,317);
  rr(ctx,669,244,319,51,11,p.inset,p.border,1.8);
  label(ctx,'PAPER PREPARATION',828.5,276,16,p.text,700,270,'center');
  rr(ctx,669,318,319,141,13,'#C3D7C5',p.border,2);
  roller(ctx,755,388,49,c*TAU*9,p.inset,p.paperInk,p.accent);
  roller(ctx,903,388,49,-c*TAU*9,p.inset,p.paperInk,p.accent);
  // Fixed guide bars occupy the clear corridor between the two cutter rollers.
  for(let j=0;j<5;j++) line(ctx,814,352+j*18,843,352+j*18,p.paperInk,2.4);
  rr(ctx,636,342,18,98,5,p.dark,p.border,1.5);
  rr(ctx,1002,365,23,44,5,p.dark,p.border,1.5);
  label(ctx,'CONTROLLED SHREDDING',828.5,498,13,p.muted,600,300,'center');

  // An outlined gravity chute routes the strips into a separate hopper.
  for(let i=0;i<7;i++) {
    const u=fract(c*5+i/7);
    const pose=chutePose(u);
    ctx.save(); ctx.globalAlpha*=edge(u,.075);
    strip(ctx,pose.x,pose.y,pose.angle,.72);
    ctx.restore();
  }
  rr(ctx,1002,365,25,44,5,p.dark,p.border,1.5);

  rr(ctx,1240,414,391,140,15,p.machine,p.border,2.3);
  rr(ctx,1262,429,347,103,8,p.inset,p.border,1.6);
  for(let row=0;row<2;row++) {
    for(let col=0;col<6;col++) strip(ctx,1293+col*56,484+row*26,(col%2?-.12:.12),.85);
  }
  // The receiving lip is an intentional foreground occlusion.
  rr(ctx,1233,413,405,17,5,'#D2E1D1',p.border,2);
  label(ctx,'PAPER OFFCUTS',1435,590,15,p.text,600,360,'center');
  label(ctx,'READY FOR FIBER RECOVERY',1435,615,11,p.muted,600,360,'center');
  rr(ctx,1255,167,361,73,14,p.tag,p.border,1.7);
  paper(ctx,1286,222,.40,p,false);
  label(ctx,'MATERIAL PREPARATION',1320,199,12,p.text,700,270);
  label(ctx,'A consistent feed into the next stage',1320,222,11,p.muted,400,270);
}

function fiberDash(ctx,x,y,l,color) {
  ctx.beginPath(); ctx.moveTo(x-l*.5,y+1.5);
  ctx.quadraticCurveTo(x,y-4,x+l*.5,y+.5);
  ctx.strokeStyle=color; ctx.lineWidth=2; ctx.stroke();
}

function refine(ctx,q,p) {
  const c=q.loopT/q.duration;
  const fiberPhase=c*MOTION.fiberCycles;
  phaseTitle(ctx,2,'REFINE THE FIBERS','Pulping, screening and pressing form one continuous material flow.',p);

  // All pipes sit behind machine boundaries; visible fiber marks follow one axis.
  pipe(ctx,509,709,389,fiberPhase,p,22);
  pipe(ctx,1038,1305,389,fiberPhase,p,22);

  // Rectangular cutaway tank: deliberately flat, with no cylindrical perspective.
  rr(ctx,79,227,453,304,23,p.machine,p.border,2.7);
  rr(ctx,100,252,411,258,14,p.inset,p.border,1.8);
  ctx.save(); rr(ctx,102,254,407,254,12); ctx.clip();
  const liquid=ctx.createLinearGradient(0,298,0,510);
  liquid.addColorStop(0,'#B7D3BB'); liquid.addColorStop(1,'#98BEA8');
  ctx.beginPath(); ctx.moveTo(101,302);
  for(let i=0;i<=64;i++) {
    const x=mix(101,512,i/64), y=302+Math.sin(TAU*(i/64-c*3))*1.6;
    ctx.lineTo(x,y);
  }
  ctx.lineTo(512,511); ctx.lineTo(101,511); ctx.closePath();
  ctx.fillStyle=liquid; ctx.fill();
  // Fibers stay in separated rows; skip the mechanical mixer clearance corridor.
  for(let row=0;row<5;row++) {
    flowMarks(ctx,121,491,329+row*37,fiberPhase+row*.19,
      '#5B8975',19,2,true,x=>ease((Math.abs(x-305)-71)/22));
  }
  ctx.restore();
  rr(ctx,241,178,129,55,12,p.machine,p.border,2.4);
  rr(ctx,261,192,89,24,5,p.inset,p.border,1.5);
  label(ctx,'MIXER',305.5,209,11,p.text,600,80,'center');
  line(ctx,305,233,305,420,p.paperInk,6);
  roller(ctx,305,420,43,c*TAU*5,'#BCD4BE',p.paperInk,p.accent);
  rr(ctx,122,531,33,20,4,p.machine,p.border,1.8);
  rr(ctx,455,531,33,20,4,p.machine,p.border,1.8);

  // Dual screening meshes, with enough padding for every moving fiber mark.
  rr(ctx,698,245,359,286,21,p.machine,p.border,2.4);
  label(ctx,'FIBER SCREEN',877.5,279,14,p.text,700,290,'center');
  rr(ctx,717,300,321,181,11,p.inset,p.border,1.8);
  flowMarks(ctx,730,1024,389,fiberPhase,p.accent,15,2,true);
  [765,923].forEach(x=>{
    rr(ctx,x-27,319,54,140,7,'rgba(178,205,184,0.28)',p.border,1.8);
    for(let i=0;i<5;i++) line(ctx,x-20,337+i*24,x+20,337+i*24,p.border,1.1);
    for(let i=0;i<3;i++) line(ctx,x-15+i*15,326,x-15+i*15,452,p.border,1.1);
  });
  // Residues have their own stationary outlet, away from the clean web.
  line(ctx,877,531,877,552,p.border,10);
  rr(ctx,812,554,131,29,8,p.inset,p.border,1.8);
  for(let i=0;i<4;i++) strip(ctx,832+i*30,568,0,.45,p.blue);

  rr(ctx,1276,244,366,290,20,p.machine,p.border,2.4);
  label(ctx,'PRESS & DEWATER',1459,278,14,p.text,700,305,'center');
  rr(ctx,1295,300,328,186,11,p.inset,p.border,1.8);
  // Thin web is tangent to both opposing roller pairs.
  rr(ctx,1307,385,305,8,3,'#E5EBD9',p.paperInk,1.5);
  [1361,1549].forEach((x,j)=>{
    roller(ctx,x,349,36,-c*TAU*4.25-j*.2,'#D5E2CE',p.paperInk,p.accent);
    roller(ctx,x,429,36,c*TAU*4.25+j*.2,'#D5E2CE',p.paperInk,p.accent);
  });
  // Fine wet-web lines pass through the nip, without shape deformation.
  flowMarks(ctx,1318,1600,389,fiberPhase,p.accent,9,1.7);
  rr(ctx,1330,499,260,14,4,'#BED6CF',p.border,1.5);

  [[305,'PULPING'],[877,'SCREENING'],[1459,'PRESSING']].forEach(([x,name],j)=>{
    circle(ctx,x-66,615,4,[p.green,p.blue,p.gold][j]);
    label(ctx,name,x-51,620,13,p.muted,600,230);
  });
  line(ctx,544,616,688,616,p.rule,1.7); arrow(ctx,688,616,10,p.border);
  line(ctx,1065,616,1257,616,p.rule,1.7); arrow(ctx,1257,616,10,p.border);
}

function remake(ctx,q,p) {
  const c=q.loopT/q.duration;
  phaseTitle(ctx,3,'MAKE A FRESH BEGINNING','Recovered fibers return as clean sheets, ready for a new use.',p);

  // Sheet-forming machine on the left, with a broad output belt.
  const sheetPhase=c*MOTION.sheetCycles;
  const sheetDistance=sheetPhase*(MOTION.sheetEnd-MOTION.sheetStart);
  belt(ctx,414,444,962,49,sheetDistance/MOTION.sheetPitch,p,20);
  // Sheets are drawn before the machine face, so they emerge from its outlet.
  for(let i=0;i<MOTION.sheetCount;i++) {
    const u=fract(sheetPhase+i/MOTION.sheetCount);
    const x=mix(MOTION.sheetStart,MOTION.sheetEnd,u);
    paperLandscape(ctx,x,390,1,true);
  }
  rr(ctx,77,218,408,316,22,p.machine,p.border,2.6);
  panelBolts(ctx,77,218,408,316);
  rr(ctx,101,242,360,54,12,p.inset,p.border,1.7);
  label(ctx,'SHEET FORMING',281,276,16,p.text,700,310,'center');
  rr(ctx,103,320,354,137,13,'#C7DCC9',p.border,1.9);
  roller(ctx,186,388,42,c*TAU*12,p.inset,p.paperInk,p.accent);
  roller(ctx,375,388,42,-c*TAU*12,p.inset,p.paperInk,p.accent);
  // Exposed formed material between the rollers is a connected machine part.
  rr(ctx,236,375,89,26,5,p.paperClean,p.paperInk,1.8);
  line(ctx,246,388,314,388,p.paperDetail,1.7);
  label(ctx,'RECOVERED FIBER IN',281,499,12,p.muted,600,310,'center');

  // Opaque outlet bezel keeps the emergence of a sheet physically coherent.
  rr(ctx,449,331,36,111,7,p.machine,p.border,2);
  rr(ctx,461,342,13,90,4,p.dark,p.border,1.2);

  // Receiving pages use the exact same silhouette, scale and baseline as the
  // belt pages. Both ends of the repeating travel are hidden by real casings.
  rr(ctx,1287,438,351,98,16,p.machine,p.border,2.3);
  for(let i=4;i>=0;i--) {
    paperLandscape(ctx,MOTION.sheetEnd+i*3,390+i*8,1,true);
  }
  rr(ctx,1286,433,352,19,6,'#D6E4D2',p.border,2);
  label(ctx,'NEW PAPER SHEETS',1462,580,15,p.text,700,360,'center');
  label(ctx,'MATERIAL READY FOR ITS NEXT USE',1462,606,11,p.muted,600,360,'center');

  // Floating only in the diagram sense: these are fixed quality/process badges.
  [[583,'CLEAN FIBERS'],[831,'CONSISTENT SHEETS'],[1079,'NEW POSSIBILITIES']].forEach(([x,name],i)=>{
    rr(ctx,x,189,220,52,12,p.tag,p.border,1.5);
    circle(ctx,x+22,215,7,null,p.accent,1.8);
    path(ctx,[[x+18,215],[x+21,218],[x+27,211]],p.accent,1.8);
    label(ctx,name,x+40,220,10,p.text,600,165);
  });
  // Fiber-cycle indicator occupies a dedicated, uncluttered lower corridor.
  line(ctx,116,594,1084,594,p.rule,2);
  flowMarks(ctx,116,1084,594,c*7,p.accent,18,2.6,false,null,144);
  recycle(ctx,1134,594,24,c*TAU,p.accent,2.6);
  label(ctx,'A CONTINUOUS PAPER CYCLE',116,628,13,p.accent,600,1000);
}

function render(ctx,timeline) {
  header(ctx);
  sceneWindow(ctx,timeline,P,[collect,refine,remake]);
  footer(ctx,timeline,P,['COLLECT','REFINE','REMAKE']);
}

  return { background, render };
})();

function draw(ctx, time, width, height) {
  const t = time;
  if (!(Number.isFinite(width) && Number.isFinite(height) && width > 0 &&
        height > 0 && Number.isFinite(t) && t >= 0)) return;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  // A 1.4-second handoff eases each complete scene out, then the next scene in.
  // Zero endpoint velocity/acceleration keeps every scene and loop join calm.
  const transitionSeconds = 1.4;
  const sceneTime = loopT - currentScene * sceneDuration;
  const rawTransition = Math.max(0, Math.min(1,
    (sceneTime - (sceneDuration - transitionSeconds)) / transitionSeconds));
  const transition = rawTransition * rawTransition * rawTransition *
    (rawTransition * (rawTransition * 6 - 15) + 10);
  const scale = Math.min(minSide / 1080, width / 1920, height / 1080);

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.setLineDash([]);
    Recycling02.background(ctx, width, height);
    ctx.translate((width - 1920 * scale) / 2, (height - 1080 * scale) / 2);
    ctx.scale(scale, scale);
    Recycling02.render(ctx, {
      t, loopT, duration, sceneCount, sceneDuration,
      currentScene, sceneProgress, rawTransition, transition, minSide
    });
  } finally {
    ctx.restore();
  }
}

