  fps: 60,
  duration: 25,
  bitrate: 100000000,
  minimumBitrate: 100000000,
  loop: true
});

/**
 * RECYCLING 01 | Smart Recycling Automated Sorting
 * Pure JavaScript Canvas 2D. No assets, imports, DOM, or external dependencies.
 * Interface: draw(ctx, time, width, height). Time is already in SECONDS.
 * 25 seconds | 3 scenes | seamless loop | 16:9 | 3840 x 2160 preferred.
 * Scales uniformly to FHD, QHD and UHD. No glow, blur, or moving background.
 *
 * REQUESTED VIDEO ENCODING: 100,000,000 bits/second (100 Mbps), 60 fps.
 * Set the renderer's video bitrate to 100 Mbps or higher. Canvas draws pixels;
 * the encoding settings below are metadata, not a video encoder.
 *
 * REVISION NOTES
 * - One shared rhythm: BEAT = 25 s / 16. Every item on every belt is released on
 *   this beat, so all three scenes move to the same tempo and loop seamlessly.
 * - Conveyor items travel at constant speed; belt treads and roller rotation are
 *   derived from that same speed (no slip). Everything else uses eased motion
 *   (zero velocity at rest, gentle acceleration and deceleration).
 * - Sorting is now causal: the diverter carriage moves to the lane of the item
 *   that is entering it, and that same item emerges in that lane.
 * - Items only appear / disappear behind opaque housings or inside a visible
 *   aperture whose border is drawn on top; nothing is cut by an invisible clip.
 * - One layout grid: 96 px page margin, 48 px panel padding, 24 px gutters.
 */
const Recycling01 = (() => {
/* This core is embedded in each delivered JavaScript file; no dependencies. */
const TAU = Math.PI * 2;
const DURATION = 25;
const BEAT = DURATION / 16;               // 1.5625 s: one item per beat in every scene

const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const fract = v => v - Math.floor(v);
const mix = (a, b, p) => a + (b - a) * p;
const wrap = (v, m) => v - Math.floor(v / m) * m;
const ease = v => { const p = clamp(v); return p*p*p*(p*(p*6-15)+10); };   // smootherstep
const easeOut = v => { const p = 1 - clamp(v); return 1 - p*p; };         // decelerate to rest
const easeIn = v => { const p = clamp(v); return p*p; };                  // accelerate from rest
const edge = (p, w = 0.09) => ease(p / w) * ease((1-p) / w);

const rgbOf = c => [1, 3, 5].map(i => parseInt(c.slice(i, i+2), 16));
const tint = (a, b, p) => {
  const A = rgbOf(a), B = rgbOf(b);
  return `rgb(${A.map((v, i) => Math.round(mix(v, B[i], p))).join(',')})`;
};
const alpha = (c, a) => `rgba(${rgbOf(c).join(',')},${a})`;

/* ------------------------------------------------------------------ */
/* Primitives                                                          */
/* ------------------------------------------------------------------ */
function rrPath(ctx, x, y, w, h, r = 12) {
  r = Math.max(0, Math.min(r, w/2, h/2));
  ctx.beginPath();
  ctx.moveTo(x+r, y);
  ctx.arcTo(x+w, y, x+w, y+h, r);
  ctx.arcTo(x+w, y+h, x, y+h, r);
  ctx.arcTo(x, y+h, x, y, r);
  ctx.arcTo(x, y, x+w, y, r);
  ctx.closePath();
}

function rr(ctx, x, y, w, h, r = 12, fill, stroke, lw = 2) {
  rrPath(ctx, x, y, w, h, r);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

function line(ctx, x1, y1, x2, y2, color, lw = 2) {
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
  ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
}

function circle(ctx, x, y, r, fill, stroke, lw = 2) {
  ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
}

function path(ctx, points, color, lw = 2, fill = null, close = false) {
  ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  if (close) ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (color) { ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke(); }
}

// mid = true centres the cap height on y (precise vertical alignment inside boxes).
function label(ctx, value, x, y, size, color, weight = 500, maxWidth = Infinity, align = 'left', mid = false) {
  ctx.save();
  ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
  ctx.font = `${weight} ${size}px Arial, Helvetica, sans-serif`;
  const measured = ctx.measureText(value).width;
  if (measured > maxWidth) {
    size *= maxWidth / measured;
    ctx.font = `${weight} ${size}px Arial, Helvetica, sans-serif`;
  }
  ctx.fillStyle = color; ctx.fillText(value, x, mid ? y + size * 0.358 : y); ctx.restore();
}

// Chevron whose geometric centre sits on (x, y) so it centres inside any box.
function arrow(ctx, x, y, size, color, angle = 0, lw = 2.5) {
  ctx.save(); ctx.translate(x, y); ctx.rotate(angle);
  path(ctx, [[-size*0.23, -size*0.38], [size*0.23, 0], [-size*0.23, size*0.38]], color, lw);
  ctx.restore();
}

function check(ctx, x, y, color) {
  circle(ctx, x, y, 9, null, color, 2);
  path(ctx, [[x-4, y+0.5], [x-1, y+3.5], [x+5, y-3.5]], color, 2);
}

function roller(ctx, x, y, r, a, fill, stroke, accent) {
  circle(ctx, x, y, r, fill, stroke, 2.4);
  ctx.save(); ctx.translate(x, y); ctx.rotate(a);
  for (let i = 0; i < 4; i++) {
    const b = i * TAU / 4;
    line(ctx, Math.cos(b)*r*.35, Math.sin(b)*r*.35, Math.cos(b)*r*.73, Math.sin(b)*r*.73, accent, 2.4);
  }
  ctx.restore(); circle(ctx, x, y, r*.18, fill, stroke, 2);
}

// Pick a tread pitch near `target` that divides the loop distance exactly,
// so treads and rollers return to the identical pose when the loop restarts.
const beltPitch = (speed, target) => speed * DURATION / Math.max(1, Math.round(speed * DURATION / target));

// travel = distance the belt surface has moved (px). Roller angle = travel / radius,
// so the roller rim and the treads always move at exactly the same speed.
function belt(ctx, x, y, w, h, travel, pitch, pal, legs = []) {
  const r = h / 2;
  rr(ctx, x, y, w, h, r, pal.belt, pal.border, 2.2);
  ctx.save();
  rrPath(ctx, x + r, y + 3, w - h, h - 6, 2); ctx.clip();
  const off = fract(travel / pitch) * pitch, inset = h * 0.2;
  for (let px = x + r - pitch + off; px <= x + w - r + pitch; px += pitch)
    line(ctx, px, y + inset, px, y + h - inset, pal.beltMark, 2);
  ctx.restore();
  const radius = Math.min(h * 0.46, pitch / Math.PI), a = travel / radius;
  roller(ctx, x + r, y + r, radius, a, pal.machine, pal.border, pal.muted);
  roller(ctx, x + w - r, y + r, radius, a, pal.machine, pal.border, pal.muted);
  legs.forEach(lx => line(ctx, lx, y + h + 4, lx, y + h + 22, pal.border, 3));
}

/* ------------------------------------------------------------------ */
/* Palette and materials                                               */
/* ------------------------------------------------------------------ */
const P = {
  text:'#EDF5F1', muted:'#A1B7BD', border:'#52717B', rule:'#35515D',
  accent:'#A2D8BE', accentInk:'#153830', tag:'#203F49',
  panelA:'#193440', panelB:'#1B3942', machine:'#254752', inset:'#17343E',
  belt:'#294650', beltMark:'#6C8990', pipe:'#1B424B',
  paper:'#DFD3B4', paperClean:'#EFF3E7', paperInk:'#5E6458', paperDetail:'#9BA994',
  colors:['#91C9E7','#E6C588','#A6D5B0','#C3B3DC'],
  names:['PLASTIC','METAL','GLASS','PAPER']
};
const PAPER_PAL = { ...P, paper:P.colors[3], paperInk:'#5D546F' };
const MAT_H = [98, 83, 98, 94];            // drawn height of each material at scale 1
const SIGNAL_BG = '#204550';

function bottle(ctx, x, bottom, s, kind = 0) {
  ctx.save(); ctx.translate(x, bottom); ctx.scale(s, s);
  ctx.beginPath(); ctx.moveTo(-11, -91); ctx.lineTo(11, -91); ctx.lineTo(11, -73);
  ctx.bezierCurveTo(11, -66, 24, -61, 24, -50);
  ctx.lineTo(24, -9); ctx.arcTo(24, 0, 15, 0, 9);
  ctx.lineTo(-15, 0); ctx.arcTo(-24, 0, -24, -9, 9);
  ctx.lineTo(-24, -50);
  ctx.bezierCurveTo(-24, -61, -11, -66, -11, -73); ctx.closePath();
  ctx.fillStyle = P.colors[kind]; ctx.fill(); ctx.strokeStyle = '#214855'; ctx.lineWidth = 3; ctx.stroke();
  rr(ctx, -13, -98, 26, 10, 3, '#DCEAE5', '#214855', 2.5);
  if (kind === 0) {
    rr(ctx, -20, -46, 40, 24, 4, '#DCECF0', '#386273', 2.4);
    line(ctx, -14, -14, 14, -14, '#467E95', 2.3);
  } else {
    line(ctx, -13, -56, -13, -21, '#568064', 2.5);
    line(ctx, -11, -10, 11, -10, '#568064', 2.5);
  }
  ctx.restore();
}

function can(ctx, x, bottom, s) {
  ctx.save(); ctx.translate(x, bottom); ctx.scale(s, s);
  rr(ctx, -28, -80, 56, 80, 9, P.colors[1], '#5E573E', 3);
  rr(ctx, -25, -83, 50, 9, 4, '#F3E1B7', '#5E573E', 2.5);
  line(ctx, -24, -9, 24, -9, '#88784D', 2.5);
  line(ctx, -17, -61, -17, -25, '#A48D59', 2.5);
  rr(ctx, -8, -80, 16, 4, 2, '#8C7E58');
  ctx.restore();
}

function paper(ctx, x, bottom, scale, palette) {
  ctx.save(); ctx.translate(x, bottom); ctx.scale(scale, scale);
  // One continuous folded-page silhouette; every corner uses the same 4 px radius.
  ctx.beginPath(); ctx.moveTo(-31, -94); ctx.lineTo(17, -94); ctx.lineTo(35, -76);
  ctx.arcTo(35, 0, -35, 0, 4); ctx.arcTo(-35, 0, -35, -94, 4); ctx.arcTo(-35, -94, 17, -94, 4);
  ctx.closePath();
  ctx.fillStyle = palette.paper; ctx.fill();
  ctx.strokeStyle = palette.paperInk; ctx.lineWidth = 3; ctx.stroke();
  path(ctx, [[17, -94], [17, -76], [35, -76]], palette.paperInk, 2.5, 'rgba(0,0,0,0.08)', true);
  for (let i = 0; i < 4; i++) line(ctx, -20, -62 + i*12, i === 3 ? 4 : 20, -62 + i*12, palette.paperInk, 2.3);
  ctx.restore();
}

function material(ctx, kind, x, bottom, s) {
  if (kind === 1) can(ctx, x, bottom, s);
  else if (kind === 3) paper(ctx, x, bottom, s, PAPER_PAL);
  else bottle(ctx, x, bottom, s, kind);
}
const materialMid = (ctx, kind, cx, cy, s) => material(ctx, kind, cx, cy + MAT_H[kind] * s / 2, s);

function bolt(ctx, x, y) {
  circle(ctx, x, y, 4, P.inset, P.border, 1.5);
  line(ctx, x-1.5, y-1.5, x+1.5, y+1.5, P.muted, 1);
}

/* ------------------------------------------------------------------ */
/* Page chrome                                                         */
/* ------------------------------------------------------------------ */
function phaseTitle(ctx, n, title, description, palette) {
  rr(ctx, 48, 35, 42, 34, 10, palette.tag, palette.border, 1.8);
  label(ctx, `0${n}`, 69, 52, 15, palette.accent, 700, 28, 'center', true);
  label(ctx, title, 106, 52, 21, palette.text, 700, 1450, 'left', true);
  label(ctx, description, 48, 96, 16, palette.muted, 400, 1550);
}

function footer(ctx, timeline, palette, names) {
  const weights = [0, 0, 0];
  weights[timeline.currentScene] = 1 - timeline.transition;
  weights[(timeline.currentScene + 1) % 3] += timeline.transition;
  line(ctx, 96, 938, 1824, 938, palette.rule, 1.4);
  names.forEach((name, i) => {
    const x = 96 + i * 576, w = weights[i];
    // Colours are interpolated (not cross-faded) so nothing doubles or ghosts.
    rr(ctx, x, 962, 34, 34, 10, tint(palette.tag, palette.accent, w), tint(palette.border, palette.accent, w), 1.8);
    label(ctx, `0${i+1}`, x + 17, 979, 13, tint(palette.muted, palette.accentInk, w), 700, 25, 'center', true);
    label(ctx, name, x + 50, 979, 17, tint(palette.muted, palette.text, w), 700, 390, 'left', true);
    ctx.save(); ctx.globalAlpha *= w;
    line(ctx, x + 50, 1000, x + 430, 1000, palette.accent, 2.4);
    ctx.restore();
  });
}

function sceneWindow(ctx, timeline, palette, scenes) {
  const X = 96, Y = 230, W = 1728, H = 670;
  const surface = ctx.createLinearGradient(X, Y, X + W, Y + H);
  surface.addColorStop(0, palette.panelA); surface.addColorStop(1, palette.panelB);
  rr(ctx, X, Y, W, H, 28, surface, palette.border, 2);
  // The drawing surface and its stationary reference marks never move.
  for (let i = 0; i < 9; i++) circle(ctx, X + 44 + i * 205, Y + H - 27, 1.4, palette.rule);
  ctx.save(); rrPath(ctx, X + 2, Y + 2, W - 4, H - 4, 26); ctx.clip(); ctx.translate(X, Y);
  const s = timeline.transition;
  const indices = s > 0 ? [timeline.currentScene, (timeline.currentScene + 1) % 3] : [timeline.currentScene];
  indices.forEach((index, j) => {
    const offset = j === 0 ? -s * W : (1 - s) * W;
    ctx.save(); ctx.translate(offset, 0);
    // Independent windows guarantee that moving scenes cannot overlap.
    ctx.beginPath(); ctx.rect(0, 0, W, H); ctx.clip();
    scenes[index](ctx, timeline, palette);
    ctx.restore();
  });
  ctx.restore();
}

function background(ctx, width, height) {
  const g = ctx.createLinearGradient(0, 0, width, height);
  g.addColorStop(0, '#112331'); g.addColorStop(.52, '#18333E'); g.addColorStop(1, '#24474A');
  ctx.fillStyle = g; ctx.fillRect(0, 0, width, height);
  // Static architectural linework, anchored to the output dimensions.
  ctx.save(); ctx.strokeStyle = 'rgba(168,205,193,0.065)'; ctx.lineWidth = Math.min(width, height) * .0011;
  for (let i = 0; i < 5; i++) {
    const x = width * (.68 + i * .065);
    ctx.beginPath(); ctx.moveTo(x, -height * .04); ctx.lineTo(x, height * .12);
    ctx.quadraticCurveTo(x, height * .19, x + height * .07, height * .19);
    ctx.lineTo(width * 1.04, height * .19 + i * height * .045); ctx.stroke();
  }
  ctx.beginPath(); ctx.arc(width * .025, height * 1.02, height * .23, Math.PI, TAU);
  ctx.stroke(); ctx.restore();
}

function header(ctx) {
  label(ctx, 'CIRCULAR SYSTEMS / MATERIAL RECOVERY', 96, 86, 14, P.accent, 700, 1000);
  label(ctx, 'SMART RECYCLING', 94, 143, 47, P.text, 700, 1050);
  label(ctx, 'Intelligent sorting. Clearly separated material streams.', 96, 181, 19, P.muted, 400, 1070);
  // 2 x 2 legend, right edge flush with the scene window (x = 1824).
  P.names.forEach((name, j) => {
    const x = 1272 + (j % 2) * 288, y = 84 + Math.floor(j / 2) * 52;
    rr(ctx, x, y, 264, 44, 11, P.tag, P.border, 1.6);
    circle(ctx, x + 22, y + 22, 4.5, P.colors[j]);
    label(ctx, name, x + 38, y + 22, 13, P.text, 600, 205, 'left', true);
  });
}

// 'n' shaped gantry: head bar plus two pillars, as one outline with exact corners.
function gantry(ctx, x0, y0, x1, y1, pw, hh, fill, stroke, lw) {
  const ro = 14, ri = 8;
  ctx.beginPath();
  ctx.moveTo(x0 + ro, y0); ctx.lineTo(x1 - ro, y0); ctx.arcTo(x1, y0, x1, y0 + ro, ro);
  ctx.lineTo(x1, y1); ctx.lineTo(x1 - pw, y1);
  ctx.lineTo(x1 - pw, y0 + hh + ri); ctx.arcTo(x1 - pw, y0 + hh, x1 - pw - ri, y0 + hh, ri);
  ctx.lineTo(x0 + pw + ri, y0 + hh); ctx.arcTo(x0 + pw, y0 + hh, x0 + pw, y0 + hh + ri, ri);
  ctx.lineTo(x0 + pw, y1); ctx.lineTo(x0, y1);
  ctx.lineTo(x0, y0 + ro); ctx.arcTo(x0, y0, x0 + ro, y0, ro); ctx.closePath();
  ctx.fillStyle = fill; ctx.fill(); ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke();
}

/* ------------------------------------------------------------------ */
/* Scene 1: identify                                                   */
/* Grid: content x 48..1680, zone y 146..526, caption bar y 574..620   */
/* ------------------------------------------------------------------ */
function identify(ctx, q, p) {
  const t = q.loopT;
  phaseTitle(ctx, 1, 'IDENTIFY THE MATERIAL', 'A controlled input stream passes through optical classification.', p);

  const FX = 48, FW = 140, OX = 1186, OW = 96;          // feeder and outlet housings
  const HY = 262, BT = 384, BH = 60, HB = BT + BH + 8;  // housing top, belt top, belt height, housing bottom
  const SX = (FX + FW + OX) / 2;                        // scanner centre = centre of the free span
  const GY = 146, HEAD = 60, HALF = 61, PIL = 26;       // gantry top, head height, window half width, pillar width
  const SC = .88;

  const xs = FX + FW - 36, xe = OX + 36;                // both ends are hidden inside the housings
  const v = ((xe - xs) / 5) / BEAT;                     // five items in transit, one released per beat
  const pitch = beltPitch(v, 68);

  belt(ctx, FX + 8, BT, OX + OW - 8 - (FX + 8), BH, v * t, pitch, p, [FX + FW + 44, OX - 44]);

  // Scanner window backdrop sits behind the items; the gantry frame sits in front of them.
  rr(ctx, SX - HALF, GY + HEAD, HALF * 2, BT - (GY + HEAD), 8, SIGNAL_BG, p.rule, 1.8);

  const items = [];
  for (let n = 0; n < 16; n++) {
    const x = xs + v * wrap(t - n * BEAT, DURATION);
    if (x <= xe) items.push({ kind: n % 4, x });
  }
  items.forEach(it => material(ctx, it.kind, it.x, BT, SC));

  // Scan beam: one smooth down-and-up pass over the height of each item as it crosses the window.
  const cls = [0, 0, 0, 0]; let scanning = 0;
  items.forEach(it => {
    cls[it.kind] = Math.max(cls[it.kind], ease((it.x - (SX - HALF - 40)) / 40) * (1 - ease((it.x - (SX + HALF)) / 40)));
    const u = (it.x - (SX - HALF)) / (HALF * 2);
    if (u > 0 && u < 1) {
      const a = edge(u, .2); scanning = Math.max(scanning, a);
      const top = BT - MAT_H[it.kind] * SC - 6, bot = BT - 5;
      ctx.save(); ctx.globalAlpha *= a;
      line(ctx, SX - HALF + 6, mix(top, bot, .5 - .5 * Math.cos(TAU * u)), SX + HALF - 6, mix(top, bot, .5 - .5 * Math.cos(TAU * u)), '#85BCAD', 3);
      ctx.restore();
    }
  });

  gantry(ctx, SX - HALF - PIL, GY, SX + HALF + PIL, BT + BH, PIL, HEAD, p.machine, p.border, 2.5);
  circle(ctx, SX - 22, GY + HEAD / 2, 4, tint(p.border, p.accent, scanning));
  label(ctx, 'SCAN', SX - 10, GY + HEAD / 2, 13, p.accent, 700, 60, 'left', true);

  // Feeder and outlet: identical height and top edge, they enclose both belt ends.
  [[FX, FW], [OX, OW]].forEach(([x, w]) => {
    rr(ctx, x, HY, w, HB - HY, 16, p.machine, p.border, 2.5);
    rr(ctx, x + 16, HY + 24, w - 32, 46, 8, p.inset, p.border, 1.8);
    arrow(ctx, x + w / 2, HY + 47, 22, p.accent, 0, 2.8);
    bolt(ctx, x + 14, HY + 12); bolt(ctx, x + w - 14, HY + 12);
  });
  line(ctx, FX + 16, HY + 96, FX + FW - 16, HY + 96, p.muted, 2);
  line(ctx, FX + 16, HY + 110, FX + FW * .6, HY + 110, p.border, 2);

  // Ruler: labels are anchored to the left edge, the scanner centre and the right edge of the stage.
  line(ctx, FX, 496, OX + OW, 496, p.rule, 1.5);
  [FX + 4, SX, OX + OW - 4].forEach(x => circle(ctx, x, 496, 4, p.accent));
  label(ctx, 'CONTROLLED INPUT', FX, 521.5, 13, p.muted, 600, 300, 'left', true);
  label(ctx, 'OPTICAL SENSOR', SX, 521.5, 13, p.muted, 600, 300, 'center', true);
  label(ctx, 'CLASSIFIED OUTPUT', OX + OW, 521.5, 13, p.muted, 600, 300, 'right', true);

  // Signature panel: 24 px padding, rows on a 76 px pitch, row of the scanned material lights up.
  const PX = 1330, PY = 146, PW = 350, PH = 380, RT = PY + 56;
  rr(ctx, PX, PY, PW, PH, 20, p.inset, p.border, 2);
  label(ctx, 'MATERIAL SIGNATURES', PX + 24, PY + 30, 15, p.text, 700, PW - 48, 'left', true);
  line(ctx, PX + 24, RT, PX + PW - 24, RT, p.rule, 1.4);
  p.names.forEach((name, j) => {
    const top = RT + j * 76, cy = top + 38, act = cls[j];
    if (j > 0) line(ctx, PX + 24, top, PX + PW - 24, top, p.rule, 1);
    if (act > .002) {
      ctx.save(); ctx.globalAlpha *= act;
      rr(ctx, PX + 12, top + 6, PW - 24, 64, 10, 'rgba(255,255,255,0.045)', p.colors[j], 1.5);
      ctx.restore();
    }
    materialMid(ctx, j, PX + 44, cy, .4);
    label(ctx, name, PX + 80, cy - 9, 13, p.text, 600, 160, 'left', true);
    for (let k = 0; k < 8; k++) {
      // Low contrast, slowly travelling signal: no strobe or flash.
      const wave = .5 + .5 * Math.cos(TAU * (k / 8 - fract(t / (BEAT * 4) + j * .21)));
      const val = mix(.30 + .32 * wave, .40 + .60 * wave, act);
      rr(ctx, PX + 80 + k * 32, cy + 6.5, 22, 7, 3, alpha(p.colors[j], val));
    }
  });

  rr(ctx, 48, 574, 1632, 46, 11, p.tag, p.rule, 1.3);
  circle(ctx, 72, 597, 4, p.accent);
  label(ctx, 'OPTICAL CLASSIFICATION', 89, 597, 13, p.accent, 600, 420, 'left', true);
  label(ctx, 'Consistent spacing  /  Independent material routes', 1656, 597, 13, p.muted, 400, 720, 'right', true);
}

/* ------------------------------------------------------------------ */
/* Scene 2: separate                                                   */
/* Four lane rows share one pitch: 96 px card + 12 px gap              */
/* ------------------------------------------------------------------ */
function sort(ctx, q, p) {
  const t = q.loopT;
  phaseTitle(ctx, 2, 'SEPARATE WITH PRECISION', 'Each material follows an isolated route to its own receiver.', p);

  const Z0 = 146, CH = 96, PITCH = 108, DH = PITCH * 3 + CH;          // lane stack: y 146..566
  const cyOf = j => Z0 + CH / 2 + j * PITCH;
  const DX = 355, DW = 245, DR = DX + DW, DCX = DX + DW / 2;          // diverter
  const RX = 1201, RW = 479, SLR = DR + 71;                           // receivers, sleeve right edge
  const FX = 48, FW = 72, IBT = 368, IBH = 45;                        // input feeder, input belt top / height
  const SC = .71, LSC = .57;

  // One belt speed for the whole scene; 3 items are always in transit on the input belt.
  const xs = 90, xe = DX + 26, v = ((xe - xs) / 3) / BEAT;
  const xls = 640, xle = RX + 24;                                     // lane item path (hidden at both ends)
  const R_ENT = (DX - xs) / v;                                        // time an item crosses the diverter edge
  const R_LANE = R_ENT + 1.0;                                         // time it leaves the diverter into its lane
  const pIn = beltPitch(v, 48), pLane = beltPitch(v, 38);

  belt(ctx, FX + 8, IBT, DX + 45 - (FX + 8), IBH, v * t, pIn, p, [168, 308]);
  for (let j = 0; j < 4; j++) belt(ctx, 640, cyOf(j) + 15, 605, 27, v * t, pLane, p);

  const inItems = [], lane = [[], [], [], []], act = [0, 0, 0, 0];
  for (let n = 0; n < 16; n++) {
    const k = n % 4, r = wrap(t - n * BEAT, DURATION), xi = xs + v * r;
    if (xi <= xe) inItems.push({ kind: k, x: xi });
    else if (r >= R_LANE) { const xl = xls + v * (r - R_LANE); if (xl <= xle) lane[k].push(xl); }
    const dt = wrap(t - (n * BEAT + R_ENT) + DURATION / 2, DURATION) - DURATION / 2;
    act[k] = Math.max(act[k], ease((dt + .35) / .35) * (1 - ease((dt - 1.2) / .5)));
  }
  inItems.forEach(it => material(ctx, it.kind, it.x, IBT, SC));
  lane.forEach((xsList, j) => xsList.forEach(x => material(ctx, j, x, cyOf(j) + 15, LSC)));

  // Input feeder (hides the item spawn point).
  rr(ctx, FX, 280, FW, IBT + IBH + 8 - 280, 14, p.machine, p.border, 2.5);
  rr(ctx, FX + 12, 300, FW - 24, 46, 8, p.inset, p.border, 1.8);
  arrow(ctx, FX + FW / 2, 323, 20, p.accent, 0, 2.8);
  label(ctx, 'MIXED', FX, 470, 14, p.muted, 600, 250, 'left', true);
  label(ctx, 'INPUT', FX, 491, 14, p.muted, 600, 250, 'left', true);

  // Lane sleeves first, then the diverter on top, so each sleeve emerges cleanly from its edge.
  for (let j = 0; j < 4; j++) {
    const cy = cyOf(j);
    rr(ctx, DR - 12, cy - 48, SLR - (DR - 12), CH, 12, p.machine, p.border, 2);
    rr(ctx, SLR - 24, cy - 43, 13, 56, 4, p.inset, p.border, 1.3);
  }
  rr(ctx, DX, Z0, DW, DH, 22, p.machine, p.border, 2.5);
  label(ctx, 'DIVERTER', DCX, Z0 + 32, 16, p.text, 700, 190, 'center', true);
  const IY = Z0 + 60, IB = Z0 + DH - 58;                              // inset 206..508
  rr(ctx, DX + 21, IY, DW - 42, IB - IY, 14, p.inset, p.rule, 2);
  const rails = [DCX - 62.5, DCX + 62.5], railTop = IY + 22, railBot = IB - 22;
  rails.forEach(x => line(ctx, x, railTop, x, railBot, p.border, 4));
  const pill = 133;
  rr(ctx, DCX - pill / 2, IB + 14, pill, 26, 7, p.inset, p.border, 1.6);
  label(ctx, 'ROUTE CONTROL', DCX, IB + 27, 10, p.muted, 600, 116, 'center', true);

  // Carriage: dwell at the lane of the item that is entering, then glide to the next lane.
  // Glide time grows with distance, so the long return stroke is never faster than it must be.
  const carY = k => railTop + 26 + k * ((railBot - railTop - 52) / 3);
  const s = (t - R_ENT) / BEAT, m = Math.floor(s), ft = (s - m) * BEAT;
  const k0 = wrap(m, 4), k1 = wrap(m + 1, 4), dist = Math.abs(k1 - k0);
  const g = ease((ft - .25) / (.7 + .2 * (dist - 1)));
  const cy = mix(carY(k0), carY(k1), g), cc = tint(p.colors[k0], p.colors[k1], g);
  const cw = 147, cx0 = DCX - cw / 2;
  rr(ctx, cx0, cy - 26, cw, 52, 10, '#3E675F', p.accent, 2);
  rr(ctx, cx0 + 18, cy - 10, 110, 20, 5, '#274D48', p.border, 1.5);
  arrow(ctx, cx0 + cw - 40, cy, 22, cc);

  for (let j = 0; j < 4; j++) {
    const cyj = cyOf(j);
    // Port tab brightens while the lane is receiving.
    rr(ctx, DR - 8.5, cyj - 12, 17, 24, 5, p.colors[j], tint(p.border, p.text, act[j]), 1.8 + act[j]);
    // Receiver card; the colour bar is clipped to the card so its corners stay exact.
    rr(ctx, RX, cyj - 48, RW, CH, 15, p.inset);
    ctx.save(); rrPath(ctx, RX, cyj - 48, RW, CH, 15); ctx.clip();
    ctx.fillStyle = p.colors[j]; ctx.fillRect(RX, cyj - 48, 13, CH); ctx.restore();
    rr(ctx, RX, cyj - 48, RW, CH, 15, null, p.border, 2);
    materialMid(ctx, j, RX + 52, cyj, .55);
    label(ctx, p.names[j], RX + 93, cyj - 9, 17, p.text, 700, 240, 'left', true);
    label(ctx, ['BOTTLE STREAM', 'ALUMINUM STREAM', 'GLASS STREAM', 'PAPER STREAM'][j], RX + 93, cyj + 13, 12, p.muted, 500, 270, 'left', true);
    check(ctx, RX + RW - 33, cyj, p.colors[j]);
  }
  label(ctx, 'FOUR MATERIALS. FOUR CLEAN ROUTES.', 1680, 597, 13, p.muted, 600, 1250, 'right', true);
}

/* ------------------------------------------------------------------ */
/* Scene 3: recover                                                    */
/* Four equal bins: 390 px wide, 24 px gutters, spanning x 48..1680    */
/* ------------------------------------------------------------------ */
function recover(ctx, q, p) {
  const t = q.loopT;
  phaseTitle(ctx, 3, 'RECOVER FOR THE NEXT CYCLE', 'Separated materials are organised and ready for downstream processing.', p);

  const CW = 390, CG = 24, CY = 146, CHH = 380, HEADH = 56;
  const WY = CY + 74, WH = 80, IS = .49, SS = .57;          // intake window, item scales
  const PERIOD = BEAT * 4;

  p.names.forEach((name, j) => {
    const x = 48 + j * (CW + CG), cx = x + CW / 2;
    rr(ctx, x, CY, CW, CHH, 20, p.inset);
    ctx.save(); rrPath(ctx, x, CY, CW, CHH, 20); ctx.clip();
    ctx.fillStyle = p.machine; ctx.fillRect(x, CY, CW, HEADH);
    line(ctx, x, CY + HEADH, x + CW, CY + HEADH, p.border, 1.8);
    ctx.restore();
    rr(ctx, x, CY, CW, CHH, 20, null, p.border, 2.2);
    circle(ctx, x + 26, CY + HEADH / 2, 5, p.colors[j]);
    label(ctx, name, x + 43, CY + HEADH / 2, 16, p.text, 700, CW - 90, 'left', true);
    label(ctx, `0${j+1}`, x + CW - 26, CY + HEADH / 2, 12, p.muted, 600, 40, 'right', true);

    // Intake window. Its own outline is the clip, drawn on top, so the item passes through a real opening.
    const WX = x + 30, WW = CW - 60, ih = MAT_H[j] * IS;
    rr(ctx, WX, WY, WW, WH, 12, '#23444C');
    ctx.save(); rrPath(ctx, WX, WY, WW, WH, 12); ctx.clip();
    // Gate bars retract smoothly while an item is passing; the gap never touches the item.
    const ps = wrap(t - j * BEAT + 1, PERIOD) - 1;
    const gate = ease((ps + .8) / .8) * (1 - ease((ps - 4.6) / .7));
    const bw = 71 * (1 - .34 * gate);
    rr(ctx, cx - 90, WY + 10, bw, 7, 3, p.border);
    rr(ctx, cx + 90 - bw, WY + 10, bw, 7, 3, p.border);
    // Enter (decelerate to rest), dwell, leave (accelerate): the item is at rest between moves.
    const ph = wrap(t - j * BEAT, PERIOD);
    const yIn = WY - 2, yRest = WY + WH / 2 + ih / 2, yOut = WY + WH + ih + 2;
    let b = null;
    if (ph < 1.7) b = mix(yIn, yRest, easeOut(ph / 1.7));
    else if (ph < 3.5) b = yRest;
    else if (ph < 5.2) b = mix(yRest, yOut, easeIn((ph - 3.5) / 1.7));
    if (b !== null) material(ctx, j, cx, b, IS);
    ctx.restore();
    rr(ctx, WX, WY, WW, WH, 12, null, p.rule, 1.7);

    // Stored stock: two shelves on an 83 px pitch, items seated 10 px above the shelf line.
    for (let row = 0; row < 2; row++) {
      const shelf = WY + WH + 18 + 83 * (row + 1);
      line(ctx, x + 30, shelf, x + CW - 30, shelf, p.rule, 1.8);
      for (let col = 0; col < 3; col++) material(ctx, j, cx + (col - 1) * 105, shelf - 10, SS);
    }
    label(ctx, 'SORTED MATERIAL', cx, CY + CHH - 21, 12, p.muted, 600, CW - 40, 'center', true);
  });

  // Outgoing flow: dashes travel at one constant speed and fade only at the two ends of the line.
  const y = 562, x0 = 48, x1 = 1668;
  line(ctx, x0, y, x1, y, p.rule, 2);
  for (let i = 0; i < 9; i++) {
    const u = fract(t / (DURATION / 3) + i / 9);
    ctx.save(); ctx.globalAlpha *= edge(u, .07);
    const x = mix(x0, x1 - 20, u);
    line(ctx, x, y, x + 20, y, p.accent, 3); ctx.restore();
  }
  arrow(ctx, 1680 - 3.2, y, 14, p.accent);
  label(ctx, 'READY FOR A NEW MATERIAL CYCLE', 864, 597, 14, p.accent, 600, 1400, 'center', true);
}

function render(ctx, timeline) {
  header(ctx);
  sceneWindow(ctx, timeline, P, [identify, sort, recover]);
  footer(ctx, timeline, P, ['IDENTIFY', 'SEPARATE', 'RECOVER']);
}

  return { background, render };
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0 && Number.isFinite(t) && t >= 0)) return;

  // A one-second quintic transition has zero velocity and acceleration at
  // both ends. Each scene occupies its own non-overlapping clipped window.
  const rawTransition = Math.max(0, Math.min(1, (sceneProgress - 0.88) / 0.12));
  const transition = rawTransition * rawTransition * rawTransition *
    (rawTransition * (rawTransition * 6 - 15) + 10);
  const scale = Math.min(minSide / 1080, width / 1920, height / 1080);

  ctx.save();
  try {
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    ctx.shadowColor = 'rgba(0,0,0,0)';
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.setLineDash([]);
    Recycling01.background(ctx, width, height);
    ctx.translate((width - 1920 * scale) / 2, (height - 1080 * scale) / 2);
    ctx.scale(scale, scale);
    Recycling01.render(ctx, {
      t, loopT, duration, sceneCount, sceneDuration,
      currentScene, sceneProgress, transition, minSide
    });
  } finally {
    ctx.restore();
  }
}

